// Small arithmetic evaluator with standard precedence (BODMAS):
// brackets → orders (powers) → ÷ × (left to right) → + − (left to right).
// Used only to verify the answer of numeric quiz questions generated by the LLM.

type Token =
  | { type: "num"; value: number }
  | { type: "op"; value: "+" | "-" | "*" | "/" | "^" }
  | { type: "open" }
  | { type: "close" };

const OP_ALIASES: Record<string, "+" | "-" | "*" | "/" | "^"> = {
  "+": "+",
  "-": "-",
  "−": "-",
  "–": "-",
  "*": "*",
  "×": "*",
  x: "*",
  "/": "/",
  "÷": "/",
  "^": "^",
};

const SUPERSCRIPTS: Record<string, string> = {
  "⁰": "0", "¹": "1", "²": "2", "³": "3", "⁴": "4",
  "⁵": "5", "⁶": "6", "⁷": "7", "⁸": "8", "⁹": "9",
};

function tokenize(input: string): Token[] {
  const tokens: Token[] = [];
  let i = 0;
  while (i < input.length) {
    const ch = input[i];
    if (/\s/.test(ch)) {
      i++;
    } else if (/[0-9.]/.test(ch)) {
      let j = i;
      while (j < input.length && /[0-9.]/.test(input[j])) j++;
      const value = Number(input.slice(i, j));
      if (Number.isNaN(value)) throw new Error(`Invalid number "${input.slice(i, j)}"`);
      tokens.push({ type: "num", value });
      i = j;
    } else if (ch in SUPERSCRIPTS) {
      // "3²" is read as 3 ^ 2.
      let digits = "";
      while (i < input.length && input[i] in SUPERSCRIPTS) digits += SUPERSCRIPTS[input[i++]];
      tokens.push({ type: "op", value: "^" }, { type: "num", value: Number(digits) });
    } else if (ch in OP_ALIASES) {
      tokens.push({ type: "op", value: OP_ALIASES[ch] });
      i++;
    } else if ("([{".includes(ch)) {
      tokens.push({ type: "open" });
      i++;
    } else if (")]}".includes(ch)) {
      tokens.push({ type: "close" });
      i++;
    } else {
      throw new Error(`Unexpected character "${ch}"`);
    }
  }
  return tokens;
}

export function evaluate(expression: string): number {
  const tokens = tokenize(expression);
  let pos = 0;

  const peek = () => tokens[pos];
  const isOp = (...ops: string[]) => {
    const t = peek();
    return t?.type === "op" && ops.includes(t.value);
  };

  // expr := term (("+" | "-") term)*
  function expr(): number {
    let value = term();
    while (isOp("+", "-")) {
      const op = (tokens[pos++] as { value: string }).value;
      const rhs = term();
      value = op === "+" ? value + rhs : value - rhs;
    }
    return value;
  }

  // term := unary (("*" | "/") unary)*
  function term(): number {
    let value = unary();
    while (isOp("*", "/")) {
      const op = (tokens[pos++] as { value: string }).value;
      const rhs = unary();
      if (op === "/" && rhs === 0) throw new Error("Division by zero");
      value = op === "*" ? value * rhs : value / rhs;
    }
    return value;
  }

  // unary := "-" unary | power
  function unary(): number {
    if (isOp("-")) {
      pos++;
      return -unary();
    }
    return power();
  }

  // power := primary ("^" unary)?   (right-associative)
  function power(): number {
    const base = primary();
    if (isOp("^")) {
      pos++;
      return base ** unary();
    }
    return base;
  }

  function primary(): number {
    const t = tokens[pos++];
    if (!t) throw new Error("Unexpected end of expression");
    if (t.type === "num") return t.value;
    if (t.type === "open") {
      const value = expr();
      if (tokens[pos++]?.type !== "close") throw new Error("Missing closing bracket");
      return value;
    }
    throw new Error("Unexpected token");
  }

  const result = expr();
  if (pos !== tokens.length) throw new Error("Unexpected trailing input");
  return result;
}

export function sameNumber(a: number, b: number): boolean {
  return Math.abs(a - b) < 1e-9;
}
